    /**
     * Method to retrieve the Exposure via an ExposurePrimaryKey.
     * @param 	id Long
     * @return 	Exposure
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Exposure handle( FindExposureQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getExposureId() );
    }
    
    /**
     * Method to retrieve a collection of all Exposures
     *
     * @param	query	FindAllExposureQuery 
     * @return 	List<Exposure> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Exposure> handle( FindAllExposureQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindExposure,
 * but only if the id matches
 *
 * @param		entity	Exposure
 */
	protected void emitFindExposure( Exposure entity ) {
		LOGGER.info("handling emitFindExposure" );
		
	    queryUpdateEmitter.emit(FindExposureQuery.class,
	                            query -> query.getFilter().getExposureId().equals(entity.getExposureId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllExposure
	 * 
	 * @param		entity	Exposure
	 */
	protected void emitFindAllExposure( Exposure entity ) {
		LOGGER.info("handling emitFindAllExposure" );
		
	    queryUpdateEmitter.emit(FindAllExposureQuery.class,
	                            query -> true,
	                            entity);
	}

